#!/bin/bash ############################################################################# # SpotifyDL v2 — FULL AUTO-DEPLOY SCRIPT # # This script does EVERYTHING in one run: # 1. Commits any local changes # 2. Pushes to GitHub # 3. Deploys to Fly.io (primary) # 4. Triggers Render deploy (mirror) # # Usage: ./scripts/full-deploy.sh # ############################################################################# set -e RED='33[0;31m' GREEN='33[0;32m' BLUE='33[0;34m' YELLOW='33[1;33m' CYAN='33[0;36m' NC='33[0m' # Banner echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${NC} echo -e ${GREEN} echo -e ${NC} echo # Configuration REPO_NAME=${REPO_NAME:-spotifydl-v2} GITHUB_USER=${GITHUB_USER:-} # Will prompt if not set APP_NAME=${FLY_APP_NAME:-spotifydl-v2} # Check prerequisites echo -e ${BLUE} echo -e ${NC} command -v git >/dev/null 2>&1 || { echo -e ${RED}; exit 1; } command -v flyctl >/dev/null 2>&1 || { echo -e ${RED}; exit 1; } command -v curl >/dev/null 2>&1 || { echo -e ${RED}; exit 1; } # Check if in git repo if [ ! -d .git ]; then echo -e ${RED} exit 1 fi # Get GitHub username if not set if [ -z $GITHUB_USER ]; then read -p Enter your GitHub username: GITHUB_USER fi # Check remote exists if ! git remote get-url origin >/dev/null 2>&1; then echo -e ${YELLOW} git remote add origin https://github.com/${GITHUB_USER}/${REPO_NAME}.git echo -e ${GREEN} fi # Step 1: Commit and Push echo -e ${BLUE} echo -e ${NC} git add -A git status if git diff --cached --quiet; then echo -e ${YELLOW} else read -p Enter commit message [Auto-deploy update]: msg msg=${msg:-Auto-deploy update} git commit -m ${msg} echo -e ${GREEN} fi echo -e ${BLUE} echo -e ${NC} git push -u origin main echo -e ${GREEN} # Step 2: Deploy to Fly.io echo -e ${BLUE} echo -e ${NC} if ! flyctl apps list 2>/dev/null | grep -q ${APP_NAME}; then echo -e ${YELLOW} flyctl launch --name ${APP_NAME} --region fra --dockerfile Dockerfile --no-deploy else echo -e ${GREEN} fi # Check/create volume if ! flyctl volumes list --app ${APP_NAME} 2>/dev/null | grep -q spotifydl_data; then echo -e ${YELLOW} flyctl volumes create spotifydl_data --size 3 --region fra --app ${APP_NAME} || true else echo -e ${GREEN} fi # Set secrets from .env if exists if [ -f .env ]; then echo -e ${BLUE} while IFS= read -r line; do [[ $line =~ ^# ]] && continue [[ -z $line ]] && continue key=$(echo $line | cut -d= -f1) value=$(echo $line | cut -d= -f2-) # Skip template values [[ $value == your_* ]] && continue [[ $value == YOUR_* ]] && continue [[ $value == changeme ]] && continue [[ -z $value ]] && continue echo -e ${CYAN} Setting: $key...${NC} flyctl secrets set ${key}=${value} --app ${APP_NAME} 2>/dev/null || echo -e ${YELLOW} Skipped $key (already set or error)${NC} done < .env echo -e ${GREEN} fi # Deploy echo -e ${BLUE} echo -e ${NC} flyctl deploy --app ${APP_NAME} echo -e ${GREEN} # Get app info echo -e ${BLUE} echo -e ${NC} flyctl status --app ${APP_NAME} FLY_URL=https://${APP_NAME}.fly.dev echo -e ${GREEN} # Step 3: Trigger Render deploy if configured if [ -n ${RENDER_API_KEY:-} ] && [ -n ${RENDER_SERVICE_ID:-} ]; then echo -e ${BLUE} echo -e ${NC} curl -s -X POST -H Authorization: Bearer ${RENDER_API_KEY} -H Content-Type: application/json -d '{clearCache: true}' https://api.render.com/v1/services/${RENDER_SERVICE_ID}/deploys >/dev/null 2>&1 || true echo -e ${GREEN} else echo -e ${YELLOW} fi # Step 4: DNS Instructions echo -e ${BLUE} echo -e ${NC} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${NC} # Get IPs for DNS echo -e ${BLUE} echo -e ${NC} flyctl ips list --app ${APP_NAME} echo echo -e ${YELLOW} echo -e ${NC} echo -e ${GREEN} echo echo -e ${BLUE} echo -e ${GREEN} echo -e ${GREEN} echo -e ${GREEN} echo -e ${GREEN} echo -e ${GREEN} echo -e ${GREEN} echo -e ${GREEN} echo -e ${GREEN} echo -e ${NC} echo -e ${YELLOW} echo -e ${YELLOW} echo -e ${YELLOW} echo -e ${NC} # Final banner echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${CYAN} echo -e ${NC} echo